                fShowBinSelect->btnAutoDeviceEjectionRemove->Enabled=true;      //JerryYang 20251020 : 渠梁半清機功能
                fMain->ModifyTester(ON_LINE);                               //Steven 20191218 : 整合修改LastSet.iTester
                fShowBinSelect->ShowBinSel();
