bool InArmSuckState()
{
    bool bHasIC=false;
    for(int i=0; i<MAX_ARM_Row; i++)
    {
        for(int j=0; j<MAX_ARM_Col; j++)
        {
            bHasIC=(bHasIC | InArmSuck.Suck[i][j].GetStatus());
        }
    }
    return bHasIC;
}
//------------------------------------------------------------------------------
bool OutArmSuckState()
{
    bool bHasIC=false;
    for(int i=0; i<MAX_ARM_Row; i++)
    {
        for(int j=0; j<MAX_ARM_Col; j++)
        {
            bHasIC = bHasIC | OutArmSuck.Suck[i][j].GetStatus();
        }
    }
    return bHasIC;
}
